mapper.select:
select r.route_id, r.tree_id, r.category_node_id, n.node_name as category_node_name, r.route_name, r.gcj02_path, r.bd09_path, r.wgs84_path, r.stroke_color, r.stroke_style, r.stroke_weight, r.status, r.create_time, r.remark from biz_scene_route r left join biz_tree_node n on n.node_id = r.category_node_id and n.del_flag = '0'
r.del_flag = '0'
and r.route_name like concat('%', #{bo.routeName}, '%')
and r.tree_id = #{bo.treeId}
and r.category_node_id = #{bo.categoryNodeId}
and r.status = #{bo.status}
order by r.create_time desc, r.route_id desc

select r.route_id, r.tree_id, r.category_node_id, n.node_name as category_node_name, r.route_name, r.gcj02_path, r.bd09_path, r.wgs84_path, r.stroke_color, r.stroke_style, r.stroke_weight, r.status, r.create_time, r.remark from biz_scene_route r left join biz_tree_node n on n.node_id = r.category_node_id and n.del_flag = '0'
r.del_flag = '0'
and r.route_name like concat('%', #{bo.routeName}, '%')
and r.tree_id = #{bo.treeId}
and r.category_node_id = #{bo.categoryNodeId}
and r.status = #{bo.status}
order by r.create_time desc, r.route_id desc
